import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents with exact half rounds to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
});

test('roundCents rounds down', () => {
  assert.equal(roundCents(124.4), 124);
});

test('roundCents rounds up', () => {
  assert.equal(roundCents(124.6), 125);
});

test('roundCents with negative', () => {
  assert.equal(roundCents(-0.5), 0);
  assert.equal(roundCents(-124.5), -124);
});

test('formatEuros basic amount', () => {
  assert.equal(formatEuros(12345), '€123.45');
});

test('formatEuros with thousands separator', () => {
  assert.equal(formatEuros(1234567), '€12,345.67');
});

test('formatEuros with negative', () => {
  assert.equal(formatEuros(-12345), '-€123.45');
});

test('parseEuros basic amount', () => {
  const result = parseEuros('123.45');
  assert.equal(result.ok, true);
  assert.equal(result.value, 12345);
});

test('parseEuros with comma separator', () => {
  const result = parseEuros('1,234.56');
  assert.equal(result.ok, true);
  assert.equal(result.value, 123456);
});

test('parseEuros invalid format returns error', () => {
  const result = parseEuros('abc');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'AMOUNT_INVALID');
});

test('RATES export contains currencies', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR', () => {
  const result = convert(100, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 100);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD'); // 100 EUR to USD
  assert.equal(result.ok, true);
  // 10000 cents * 1.085 = 10850 cents = $108.50
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP'); // 100 EUR to GBP
