import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros } from '../src/money.js';

test('roundCents rounds half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(2.6), 3);
  assert.equal(roundCents(-0.5), 0);
});

test('roundCents ignores binary noise', () => {
  assert.equal(roundCents(0.1 * 3 * 100), 30);
  assert.equal(roundCents(1.005 * 100), 100);
});

test('formatEuros adds the sign, thousands separators and two decimals', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
  assert.equal(formatEuros(5), '€0.05');
  assert.equal(formatEuros(-250), '-€2.50');
  assert.equal(formatEuros(100000000), '€1,000,000.00');
});

test('parseEuros reads what people type', () => {
  assert.deepEqual(parseEuros('12'), { ok: true, value: 1200 });
  assert.deepEqual(parseEuros('12.5'), { ok: true, value: 1250 });
  assert.deepEqual(parseEuros('1,234.56'), { ok: true, value: 123456 });
  assert.deepEqual(parseEuros('12.345'), { ok: false, error: 'AMOUNT_INVALID' });
  assert.deepEqual(parseEuros('abc'), { ok: false, error: 'AMOUNT_INVALID' });
});

